function icon(name,cls=''){return `<span class="sa-icon ${cls}">${ICONS[name]||''}</span>`}
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=ICONS[el.dataset.icon]||'';el.classList.add('sa-icon')})}


async function applyPlatformSettings(){
  try{
    let settings=await api('/api/settings');
    if(settings.primary_color){
      document.documentElement.style.setProperty('--blue',settings.primary_color);
      document.documentElement.style.setProperty('--blue-600',settings.primary_color);
    }
  }catch{}
}

function toast(t,b=false){toastEl.textContent=t;toastEl.className=b?'show bad':'show';setTimeout(()=>toastEl.className='',2800)}
async function api(path,opt={}){opt.headers={'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{}),...(opt.headers||{})};let r;try{r=await fetch(path,opt)}catch{throw Error('Não foi possível conectar ao servidor. Mantenha a janela preta aberta.')}let d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'Erro inesperado');return d}
function fileToData(file,max=1500){return new Promise((res,rej)=>{if(!file)return res('');if(file.size>5*1024*1024)return rej(Error('A imagem deve ter no máximo 5 MB.'));let fr=new FileReader();fr.onload=()=>{let i=new Image();i.onload=()=>{let sc=Math.min(1,max/Math.max(i.width,i.height)),c=document.createElement('canvas');c.width=Math.round(i.width*sc);c.height=Math.round(i.height*sc);c.getContext('2d').drawImage(i,0,0,c.width,c.height);res(c.toDataURL('image/jpeg',.82))};i.src=fr.result};fr.onerror=rej;fr.readAsDataURL(file)})}
function currentVideoLimit(){return Number(me?.video_limit_bytes||250*1024*1024)}
function currentAudioLimit(){return Number(me?.audio_limit_bytes||100*1024*1024)}
function fileExt(name=''){let m=name.toLowerCase().match(/\.[^.]+$/);return m?m[0]:''}
const documentExts=new Set(['.pdf','.doc','.docx','.odt','.rtf','.txt','.md','.xls','.xlsx','.ods','.csv','.ppt','.pptx','.odp','.xml','.json','.yaml','.yml']);
const archiveExts=new Set(['.zip','.rar','.7z']);
const technicalExts=new Set(['.rew','.mdat','.trace','.frd','.zma','.cal','.mic','.ssn','.scn','.scene','.show','.preset','.fxp','.fxb','.vstpreset','.ir','.syx','.mid','.midi','.cue','.rider']);
function allowedGenericFile(f){let e=fileExt(f.name);return documentExts.has(e)||archiveExts.has(e)||technicalExts.has(e)}
function genericFileLimit(f){let e=fileExt(f.name);if(archiveExts.has(e))return Number(me?.archive_limit_label?.includes('GB')?parseFloat(me.archive_limit_label)*1024**3:parseFloat(me?.archive_limit_label||500)*1024**2);if(documentExts.has(e))return Number(me?.document_limit_label?.includes('GB')?parseFloat(me.document_limit_label)*1024**3:parseFloat(me?.document_limit_label||100)*1024**2);return Number(me?.technical_file_limit_label?.includes('GB')?parseFloat(me.technical_file_limit_label)*1024**3:parseFloat(me?.technical_file_limit_label||250)*1024**2)}
function humanSize(n){return n>=1024**3?`${Math.round(n/1024**3)} GB`:`${Math.round(n/1024**2)} MB`}
function fileToPostMedia(file){return new Promise(async(res,rej)=>{if(!file)return res({data:'',type:'',name:'',size:0,file:null});if(file.type.startsWith('image/')){try{return res({data:await fileToData(file,1800),type:'image/jpeg',name:file.name,size:file.size,file:null})}catch(e){return rej(e)}}if(['audio/mpeg','audio/mp3','audio/wav','audio/x-wav','audio/ogg','audio/mp4','audio/aac','audio/flac','audio/x-flac'].includes(file.type)){let limit=currentAudioLimit();if(file.size>limit)return rej(Error(`Seu plano ${me?.plan_label||'Gratuito'} permite áudios de até ${humanSize(limit)}.`));return res({data:'',type:file.type,name:file.name,size:file.size,file})}if(['video/mp4','video/webm'].includes(file.type)){let limit=currentVideoLimit();if(file.size>limit)return rej(Error(`Seu plano ${me?.plan_label||'Gratuito'} permite vídeos de até ${humanSize(limit)}.`));let fr=new FileReader();fr.onload=()=>res({data:fr.result,type:file.type,name:file.name,size:file.size,file:null});fr.onerror=()=>rej(Error('Não foi possível ler o vídeo.'));fr.readAsDataURL(file);return}if(allowedGenericFile(file)){let limit=genericFileLimit(file);if(file.size>limit)return rej(Error(`Este arquivo ultrapassa o limite do seu plano (${humanSize(limit)}).`));return res({data:'',type:file.type||'application/octet-stream',name:file.name,size:file.size,file})}return rej(Error('Formato não permitido. Use documentos, planilhas, apresentações, ZIP/RAR/7Z ou arquivos técnicos de áudio.'))})}
function clearPostObjectUrl(){if(postObjectUrl){URL.revokeObjectURL(postObjectUrl);postObjectUrl=''}}
function showPostMediaPreview(){let isVideo=postMediaType.startsWith('video/'),isAudio=postMediaType.startsWith('audio/'),isFile=!!postMediaType&&!isVideo&&!isAudio&&!postMediaType.startsWith('image/');postPreview.hidden=!postImage||isVideo||isAudio||isFile;postVideoPreview.hidden=!postImage||!isVideo;postAudioPreview.hidden=!postImage||!isAudio;postFilePreview.hidden=!isFile;if(isFile){postFilePreview.innerHTML=`<b>${esc(postMediaName||'Arquivo')}</b><small>${humanSize(postMediaSize||pendingPostFile?.size||0)} · pronto para enviar</small>`}if(postImage){if(isVideo){postVideoPreview.src=postImage;postPreview.removeAttribute('src');postAudioPreview.pause();postAudioPreview.removeAttribute('src')}else if(isAudio){postAudioPreview.src=postImage;postPreview.removeAttribute('src');postVideoPreview.pause();postVideoPreview.removeAttribute('src')}else if(!isFile){postPreview.src=postImage;postVideoPreview.pause();postVideoPreview.removeAttribute('src');postAudioPreview.pause();postAudioPreview.removeAttribute('src')}}else if(!isFile){postPreview.removeAttribute('src');postVideoPreview.pause();postVideoPreview.removeAttribute('src');postAudioPreview.pause();postAudioPreview.removeAttribute('src')}removePostImage.hidden=!postImage&&!pendingPostFile}
async function uploadPendingAudio(file){let r;try{r=await fetch('/api/media/audio',{method:'POST',headers:{Authorization:'Bearer '+token,'Content-Type':file.type,'X-File-Name':encodeURIComponent(file.name)},body:file})}catch{throw Error('Não foi possível enviar o áudio. Verifique se o servidor está aberto.')}let d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'Falha no upload do áudio.');return d}
async function uploadPendingFile(file){let r=await fetch('/api/media/file',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/octet-stream','X-File-Name':encodeURIComponent(file.name),'X-File-Type':file.type||'application/octet-stream','Content-Length':String(file.size)},body:file});let data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||'Falha ao enviar o arquivo.');return data}

function avatar(u,cls=''){return u.avatar?`<img class="avatar ${cls}" src="${u.avatar}" alt="">`:`<div class="avatar ${cls}">${esc(u.name).charAt(0)}</div>`}
function lines(v){return esc(v||'').split(/[,\n]/).filter(Boolean).map(x=>`<span class="skill">${x.trim()}</span>`).join('')}
function tab(w){login.hidden=w!=='login';register.hidden=w!=='register';msg.textContent=''}
async function boot(){await applyPlatformSettings();if(token){try{me=(await api('/api/me')).user;showApp();return}catch{localStorage.removeItem('sociaudio_token');token=''}}auth.hidden=false;auth.style.display='grid';app.hidden=true}
function showApp(){auth.hidden=true;auth.style.display='none';app.hidden=false;app.style.display='block';headerName.textContent=me.name;if(window.sidebarName)sidebarName.textContent=me.name;if(window.sidebarRole)sidebarRole.textContent=`${me.role} · ${me.plan_label||'Gratuito'}`;adminNav.hidden=!me.is_admin;hydrateIcons();loadAll()}
async function loadAll(){try{[posts,users,communities,notifications]=await Promise.all([api('/api/posts'),api('/api/users'),api('/api/communities'),api('/api/notifications')]);bellCount.textContent=notifications.unread||'';render()}catch(e){toast(e.message,true)}}
loginTab.onclick=()=>{tab('login');loginTab.classList.add('active');registerTab.classList.remove('active')};registerTab.onclick=()=>{tab('register');registerTab.classList.add('active');loginTab.classList.remove('active')};
login.onsubmit=async e=>{e.preventDefault();try{token=(await api('/api/login',{method:'POST',body:JSON.stringify({email:le.value,password:lp.value})})).token;localStorage.setItem('sociaudio_token',token);me=(await api('/api/me')).user;showApp()}catch(e){msg.textContent=e.message}};
register.onsubmit=async e=>{e.preventDefault();try{token=(await api('/api/register',{method:'POST',body:JSON.stringify({name:rn.value,email:re.value,password:rp.value,role:rr.value,city:rc.value})})).token;localStorage.setItem('sociaudio_token',token);me=(await api('/api/me')).user;showApp()}catch(e){msg.textContent=e.message}};
logoutBtn.onclick=async()=>{try{await api('/api/logout',{method:'POST'})}catch{}localStorage.removeItem('sociaudio_token');location.reload()};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});bellBtn.onclick=()=>{view='notifications';render()};
newPostBtn.onclick=()=>openNewPost();closePost.onclick=()=>{postDlg.close();resetPostDialog()};
pimg.onchange=async()=>{try{let m=await fileToPostMedia(pimg.files[0]);clearPostObjectUrl();pendingPostFile=m.file||null;postObjectUrl=pendingPostFile?URL.createObjectURL(pendingPostFile):'';postImage=postObjectUrl||m.data;postMediaType=m.type;postMediaName=m.name;postMediaSize=m.size||0;imageChanged=true;showPostMediaPreview()}catch(e){pimg.value='';toast(e.message,true)}};removePostImage.onclick=()=>{clearPostObjectUrl();pendingPostFile=null;postImage='';postMediaType='';postMediaName='';postMediaSize=0;imageChanged=true;pimg.value='';showPostMediaPreview()};
function resetPostDialog(){editingPostId=null;imageChanged=false;clearPostObjectUrl();pendingPostFile=null;postImage='';postMediaType='';postMediaName='';postMediaSize=0;postForm.reset();purl.value='';pimg.accept='image/*,video/mp4,video/webm,audio/mpeg,audio/wav,audio/ogg,audio/mp4,audio/aac,audio/flac,.pdf,.doc,.docx,.odt,.rtf,.txt,.md,.xls,.xlsx,.ods,.csv,.ppt,.pptx,.odp,.zip,.rar,.7z,.xml,.json,.yaml,.yml,.rew,.mdat,.trace,.frd,.zma,.cal,.mic,.ssn,.scn,.scene,.show,.preset,.fxp,.fxb,.vstpreset,.ir,.syx,.mid,.midi,.cue,.rider';postMediaLabel.textContent='Adicionar foto, vídeo, áudio ou arquivo';postMediaHelp.textContent='Escolha uma mídia para anexar à publicação.';showPostMediaPreview();postDialogTitle.textContent='Nova publicação';postSubmit.textContent='Publicar'}
function openNewPost(kind=''){resetPostDialog();if(kind==='video'){pimg.accept='video/mp4,video/webm';postMediaLabel.textContent='Escolher vídeo';postMediaHelp.textContent=`Plano ${me?.plan_label||'Gratuito'}: vídeos MP4/WebM de até ${me?.video_limit_label||'250 MB'}.`;pt.value='Experiência'}else if(kind==='audio'){pimg.accept='audio/mpeg,audio/wav,audio/ogg,audio/mp4,audio/aac,audio/flac';postMediaLabel.textContent='Escolher áudio';postMediaHelp.textContent=`Plano ${me?.plan_label||'Gratuito'}: áudios MP3, WAV, OGG, M4A/AAC ou FLAC de até ${me?.audio_limit_label||'100 MB'}.`;pt.value='Experiência'}else if(kind==='photo'){pimg.accept='image/*';postMediaLabel.textContent='Escolher foto';postMediaHelp.textContent='Clique em Escolher foto para anexar uma imagem.'}else if(kind==='file'){pimg.accept='.pdf,.doc,.docx,.odt,.rtf,.txt,.md,.xls,.xlsx,.ods,.csv,.ppt,.pptx,.odp,.zip,.rar,.7z,.xml,.json,.yaml,.yml,.rew,.mdat,.trace,.frd,.zma,.cal,.mic,.ssn,.scn,.scene,.show,.preset,.fxp,.fxb,.vstpreset,.ir,.syx,.mid,.midi,.cue,.rider';postMediaLabel.textContent='Escolher arquivo';postMediaHelp.textContent=`Documentos até ${me?.document_limit_label||'100 MB'}; compactados até ${me?.archive_limit_label||'500 MB'}; arquivos técnicos até ${me?.technical_file_limit_label||'250 MB'}.`}postDlg.showModal()}
function editPost(id){let p=posts.find(x=>x.id===id);if(!p)return toast('Publicação não encontrada.',true);clearPostObjectUrl();pendingPostFile=null;editingPostId=id;imageChanged=false;pt.value=p.type;pc.value=p.category;pti.value=p.title;pb.value=p.body;purl.value=p.link_url||'';postImage=p.media_data||p.image_data||'';postMediaType=p.media_type||(postImage.startsWith('data:image/')?'image/jpeg':'');postMediaName=p.media_name||'';postMediaSize=Number(p.media_size||0);showPostMediaPreview();postDialogTitle.textContent='Editar publicação';postSubmit.textContent='Salvar alterações';postDlg.showModal()}
postForm.onsubmit=async e=>{e.preventDefault();let btn=postSubmit;btn.disabled=true;btn.textContent=postMediaType.startsWith('audio/')?'Enviando áudio...':postMediaType.startsWith('video/')?'Enviando vídeo...':'Salvando...';try{let uploaded=null;if(pendingPostFile&&postMediaType.startsWith('audio/'))uploaded=await uploadPendingAudio(pendingPostFile);else if(pendingPostFile&&!postMediaType.startsWith('image/')&&!postMediaType.startsWith('video/'))uploaded=await uploadPendingFile(pendingPostFile);let payload={type:pt.value,category:pc.value,title:pti.value,body:pb.value,link_url:purl.value.trim()};if(!editingPostId||imageChanged){payload.media_data=uploaded?.media_data??postImage;payload.media_type=uploaded?.media_type??postMediaType;payload.media_name=uploaded?.media_name??postMediaName;payload.media_size=uploaded?.size??postMediaSize}await api(editingPostId?`/api/posts/${editingPostId}/edit`:'/api/posts',{method:'POST',body:JSON.stringify(payload)});let edited=!!editingPostId;postDlg.close();resetPostDialog();toast(edited?'Publicação atualizada.':'Publicação criada.');loadAll()}catch(e){toast(e.message,true)}finally{btn.disabled=false;btn.textContent=editingPostId?'Salvar alterações':'Publicar'}};
async function like(id){await api(`/api/posts/${id}/like`,{method:'POST'});loadAll()} async function bookmark(id){await api(`/api/posts/${id}/bookmark`,{method:'POST'});loadAll()}
function toggleComments(id){openCommentPosts.has(id)?openCommentPosts.delete(id):openCommentPosts.add(id);render()} async function submitComment(id){let el=document.getElementById(`comment-${id}`),body=(el?.value||'').trim();if(!body)return toast('Digite um comentário.',true);try{await api(`/api/posts/${id}/comments`,{method:'POST',body:JSON.stringify({body})});openCommentPosts.add(id);toast('Comentário publicado.');await loadAll()}catch(e){toast(e.message,true)}}
async function joinCommunity(id){await api(`/api/communities/${id}/join`,{method:'POST'});loadAll()} async function followUser(id){await api(`/api/users/${id}/follow`,{method:'POST'});loadAll()}
async function featurePost(id){await api(`/api/admin/posts/${id}/feature`,{method:'POST'});loadAll()} async function removePost(id){if(!confirm('Deseja realmente excluir esta publicação? Esta ação não poderá ser desfeita.'))return;try{await api(`/api/posts/${id}`,{method:'DELETE'});toast('Publicação excluída.');await loadAll()}catch(e){toast(e.message,true)}}
function safeLink(url){try{let u=new URL(url);return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return ''}} function linkCard(url){let href=safeLink(url);if(!href)return '';let host='';try{host=new URL(href).hostname.replace(/^www\./,'')}catch{}return `<a class="post-link" href="${esc(href)}" target="_blank" rel="noopener noreferrer"><span class="link-icon">${icon('link')}</span><span><b>${esc(host||'Abrir link')}</b><small>${esc(href)}</small></span><strong>Abrir</strong></a>`} function fileCard(md,mt,name,size){let ext=fileExt(name),pdf=ext==='.pdf';return `<div class="post-file-card"><span>${icon(ext==='.pdf'?'file':'file')}</span><div><b>${esc(name||'Arquivo')}</b><small>${esc(ext.replace('.','').toUpperCase()||'ARQUIVO')} · ${humanSize(Number(size||0))}</small></div>${pdf?`<a class="secondary btn" href="${esc(md)}" target="_blank" rel="noopener">Visualizar</a>`:''}<a class="primary btn" href="${esc(md)}" download="${esc(name||'arquivo')}">Baixar</a></div>`} function commentsBlock(p){if(!openCommentPosts.has(p.id))return '';return `<section class="comments-panel"><div class="comment-compose">${avatar(me)}<textarea id="comment-${p.id}" placeholder="Escreva um comentário..."></textarea><button class="primary" onclick="submitComment(${p.id})">Comentar</button></div>${p.answers.length?p.answers.map(a=>`<div class="answer"><b>${esc(a.name)}${a.is_admin?' ✓':''}</b><span class="meta"> ${esc(a.role)} · ${new Date(a.created_at).toLocaleString('pt-BR')}</span><p>${esc(a.body)}</p></div>`).join(''):'<p class="no-comments">Ainda não há comentários. Seja o primeiro a comentar.</p>'}</section>`} function postCard(p){let canEdit=p.user_id===me.id||me.is_admin;let edited=p.updated_at?` · <span class="edited">Editado em ${new Date(p.updated_at).toLocaleString('pt-BR')}</span>`:'';return `<article class="card post ${p.is_featured?'featured':''}"><div class="post-author">${avatar(p)}<div><button class="link-name" onclick="openProfile(${p.user_id})"><b>${esc(p.name)}${p.is_admin?' ✓':''}</b></button><div class="meta">${esc(p.role)} · ${new Date(p.created_at).toLocaleString('pt-BR')}${edited}</div></div>${p.is_featured?'<span class="featured-label">DESTAQUE</span>':''}</div><h2>${esc(p.title)}</h2><div><span class="tag">${esc(p.type)}</span><span class="tag muted">${esc(p.category)}</span></div><p class="post-body">${esc(p.body)}</p>${linkCard(p.link_url||'')}${(()=>{let md=p.media_data||p.image_data||'',mt=p.media_type||(md.startsWith('data:image/')?'image/jpeg':'');if(!md)return '';return mt.startsWith('video/')?`<video class="post-video" src="${esc(md)}" controls preload="metadata" playsinline onerror="this.outerHTML='<div class=&quot;video-error&quot;>Não foi possível reproduzir este vídeo. Envie novamente em MP4 com vídeo H.264 e áudio AAC.</div>'"></video>`:mt.startsWith('audio/')?`<div class="post-audio-wrap"><div class="post-audio-head">${icon('audio')}<span><b>${esc(p.media_name||'Áudio')}</b><small>Publicação de áudio</small></span></div><audio class="post-audio" src="${esc(md)}" controls preload="metadata" onerror="this.closest('.post-audio-wrap').innerHTML='<div class=&quot;video-error&quot;>Não foi possível reproduzir este áudio. Tente MP3, WAV, OGG ou M4A.</div>'"></audio></div>`:mt.startsWith('image/')?`<img class="post-image" src="${md}" alt="Mídia da publicação">`:fileCard(md,mt,p.media_name,p.media_size)})()}<div class="engagement-summary"><span>${p.likes} curtida(s)</span><span>${p.comments} comentário(s)</span></div><div class="actions"><button class="${p.liked?'active':''}" onclick="like(${p.id})">${icon('like')}<span>Curtir</span></button><button class="${openCommentPosts.has(p.id)?'active':''}" onclick="toggleComments(${p.id})">${icon('comment')}<span>Comentários</span></button><button onclick="navigator.clipboard?.writeText(location.href);toast('Link copiado.')">${icon('share')}<span>Compartilhar</span></button><button class="${p.bookmarked?'active':''}" onclick="bookmark(${p.id})">${icon('saved')}<span>${p.bookmarked?'Salvo':'Salvar'}</span></button>${canEdit?`<button onclick="editPost(${p.id})">${icon('edit')}<span>Editar</span></button><button class="danger-action" onclick="removePost(${p.id})">${icon('trash')}<span>Excluir</span></button>`:''}${me.is_admin?`<button class="post-more" onclick="featurePost(${p.id})" title="Destacar">${icon('more')}</button>`:''}</div>${commentsBlock(p)}</article>`}
function renderFeed(saved=false){let q=(search.value||'').toLowerCase(),list=posts.filter(p=>(!saved||p.bookmarked)&&(p.title+' '+p.body+' '+p.category+' '+p.name).toLowerCase().includes(q));content.innerHTML=`<section class="card composer"><div class="composer-main">${avatar(me)}<button onclick="openNewPost()">No que você está pensando, ${esc(me.name.split(' ')[0])}?</button></div><div class="composer-tools"><button onclick="openNewPost('video')">${icon('video')}<span>Vídeo</span></button><button onclick="openNewPost('photo')">${icon('photo')}<span>Foto</span></button><button onclick="openNewPost('audio')">${icon('audio')}<span>Áudio</span></button><button onclick="openNewPost('file')">${icon('file')}<span>Arquivo</span></button></div></section><section class="story-strip"><button class="story create-story" onclick="openNewPost()"><span class="story-plus">${icon('plus')}</span><b>Criar story</b></button><div class="story story-console"><span>${avatar(me)}</span><b>Seu conteúdo</b></div><div class="story story-stage"><span>${icon('audio')}</span><b>Dicas de áudio</b></div><div class="story story-mic"><span>${icon('professionals')}</span><b>Profissionais</b></div></section>${list.length?list.map(postCard).join(''):'<div class="empty">Nenhuma publicação encontrada.</div>'}`}
function renderExperts(){content.innerHTML=`<div class="page-title"><h1>Profissionais</h1><p>Encontre especialistas, conheça seus serviços e faça contatos.</p></div><div class="people-grid">${users.map(u=>`<article class="card person"><div class="mini-cover" style="${u.cover?`background-image:url('${u.cover}')`:''}"></div>${avatar(u,'big')}<h3>${esc(u.name)}${u.is_admin?' ✓':''}</h3><b>${esc(u.role)}</b><p class="availability">● ${esc(u.availability||'Disponível para trabalhos')}</p><p class="meta">${icon('location')} ${esc(u.city||'Cidade não informada')}</p><div class="skills">${lines(u.specialties)}</div><div class="follow-stats"><span><b>${u.followers}</b> seguidores</span><span><b>${u.following}</b> seguindo</span></div><button class="secondary" onclick="openProfile(${u.id})">Ver perfil</button>${u.id!==me.id?`<button class="${u.is_following?'secondary':'primary'}" onclick="followUser(${u.id})">${u.is_following?'Deixar de seguir':'Seguir'}</button>`:''}</article>`).join('')}</div>`}
async function openProfile(id){try{let u=await api(`/api/users/${id}/profile`);let portfolio=(u.portfolio_links||'').split(/\n/).map(x=>x.trim()).filter(Boolean);let history=(u.work_history||'').split(/\n/).map(x=>x.trim()).filter(Boolean);content.innerHTML=`<article class="profile-public pro-v10 card"><div class="cover" style="${u.cover?`background-image:url('${u.cover}')`:''}"></div><div class="profile-head">${avatar(u,'huge')}<div class="profile-identity"><h1>${esc(u.name)}${u.is_admin?' <span class="verified">✓</span>':''}</h1><h2>${esc(u.headline||u.role)}</h2>${u.company?`<p class="company-line">${esc(u.company)}</p>`:''}<p class="availability">● ${esc(u.availability||'Disponível para trabalhos')}</p><p>${icon('location')} ${esc(u.city||'Cidade não informada')} ${u.service_region?`· Atende: ${esc(u.service_region)}`:''}</p></div></div><div class="profile-actions">${u.id!==me.id?`<button class="${u.is_following?'secondary':'primary'}" onclick="followUser(${u.id});openProfile(${u.id})">${u.is_following?'Deixar de seguir':'Seguir'}</button><button class="primary" onclick="openQuote(${u.id},${JSON.stringify(u.name)})">Solicitar orçamento</button>`:`<button class="primary" onclick="view='profile';render()">Editar meu perfil</button>`}${u.whatsapp?`<a class="secondary btn" target="_blank" href="https://wa.me/${u.whatsapp.replace(/\D/g,'')}">WhatsApp</a>`:''}</div><div class="pro-summary"><div><b>${esc(u.experience||'—')}</b><span>Experiência</span></div><div><b>${esc(u.completed_projects||'—')}</b><span>Projetos</span></div><div><b>${u.followers}</b><span>Seguidores</span></div><div><b>${esc(u.response_time||'Até 24h')}</b><span>Tempo de resposta</span></div></div><section><h2>Sobre</h2><p>${esc(u.bio||'Perfil em construção.')}</p></section><section><h2>Especialidades</h2><div class="skills">${lines(u.specialties)}</div></section><section><h2>Serviços oferecidos</h2><p>${esc(u.services||'Não informado.')}</p></section><section><h2>Equipamentos que domina</h2><div class="skills">${lines(u.equipment)}</div></section><section><h2>Experiência profissional</h2>${history.length?`<div class="timeline">${history.map(x=>`<div><i></i><p>${esc(x)}</p></div>`).join('')}</div>`:`<p>${esc(u.experience||'Não informada.')}</p>`}</section><section><h2>Portfólio</h2>${portfolio.length?`<div class="portfolio-grid">${portfolio.map((x,i)=>`<a href="${esc(safeLink(x))}" target="_blank" rel="noopener"><b>Projeto ${i+1}</b><small>${esc(x)}</small></a>`).join('')}</div>`:'<p>Nenhum link de portfólio cadastrado.</p>'}</section><section><h2>Certificações</h2><p>${esc(u.certifications||'Não informadas.')}</p></section><section class="contacts"><h2>Contato profissional</h2>${u.instagram?`<p>Instagram: ${esc(u.instagram)}</p>`:''}${u.website?`<p>Site: <a href="${esc(safeLink(u.website))}" target="_blank">${esc(u.website)}</a></p>`:''}</section></article>`}catch(e){toast(e.message,true)}}
function renderCommunities(){content.innerHTML='<div class="page-title"><h1>Comunidades</h1><p>Participe de grupos especializados em equipamentos e áreas do áudio.</p></div><div class="community-grid">'+communities.map(c=>`<article class="card community"><div class="community-icon">${c.icon}</div><h3>${esc(c.name)}</h3><span class="tag">${esc(c.category)}</span><p>${esc(c.description)}</p><small>${c.members} membro(s)</small><button class="${c.joined?'secondary':'primary'}" onclick="joinCommunity(${c.id})">${c.joined?'Sair da comunidade':'Participar'}</button></article>`).join('')+'</div>'}
function renderProfile(){avatarImage=me.avatar||'';coverImage=me.cover||'';content.innerHTML=`<div class="page-title"><h1>Meu perfil profissional</h1><p>Plano atual: <b>${esc(me.plan_label||'Gratuito')}</b> · limite por vídeo: <b>${esc(me.video_limit_label||'250 MB')}</b></p></div><form class="card profile-grid" onsubmit="saveProfile(event)"><div class="wide cover-editor" style="${me.cover?`background-image:url('${me.cover}')`:''}"><label>Alterar capa<input id="pcov" type="file" accept="image/*"></label></div><div class="wide avatar-editor">${avatar(me,'huge')}<label>Alterar foto<input id="pav" type="file" accept="image/*"></label></div><label>Nome<input id="pn" value="${esc(me.name)}" required></label><label>Profissão<input id="pr" value="${esc(me.role)}" required></label><label class="wide">Título profissional<input id="phl" value="${esc(me.headline||'')}" placeholder="Ex.: Especialista em áudio ao vivo e sistemas de som"></label><label>Empresa<input id="pco" value="${esc(me.company||'')}" placeholder="Ex.: EB Áudio"></label><label>Cidade<input id="pcy" value="${esc(me.city||'')}"></label><label>Região de atendimento<input id="preg" value="${esc(me.service_region||'')}"></label><label>Tempo de experiência<input id="pex" value="${esc(me.experience||'')}"></label><label>Projetos concluídos<input id="ppj" value="${esc(me.completed_projects||'')}" placeholder="Ex.: 250+"></label><label>Tempo de resposta<input id="prt" value="${esc(me.response_time||'')}" placeholder="Ex.: Responde em até 2 horas"></label><label>Disponibilidade<select id="pavl"><option ${me.availability==='Disponível para trabalhos'?'selected':''}>Disponível para trabalhos</option><option ${me.availability==='Disponível apenas para consultorias'?'selected':''}>Disponível apenas para consultorias</option><option ${me.availability==='Indisponível no momento'?'selected':''}>Indisponível no momento</option></select></label><label class="wide">Especialidades<input id="psp" value="${esc(me.specialties||'')}" placeholder="FOH, Igrejas, Streaming..."></label><label class="wide">Serviços oferecidos<textarea id="psv">${esc(me.services||'')}</textarea></label><label class="wide">Equipamentos que domina<input id="peq" value="${esc(me.equipment||'')}" placeholder="Ui24R, M32, X32, Yamaha..."></label><label class="wide">Histórico profissional<textarea id="pwh" placeholder="Uma experiência por linha">${esc(me.work_history||'')}</textarea></label><label class="wide">Links do portfólio<textarea id="ppl" placeholder="Um link por linha">${esc(me.portfolio_links||'')}</textarea></label><label class="wide">Certificações<textarea id="pce">${esc(me.certifications||'')}</textarea></label><label>WhatsApp profissional<input id="pwa" value="${esc(me.whatsapp||'')}" placeholder="5547999999999"></label><label>Instagram<input id="pig" value="${esc(me.instagram||'')}" placeholder="@usuario"></label><label class="wide">Site<input id="pweb" value="${esc(me.website||'')}"></label><label class="wide">Biografia<textarea id="pbi">${esc(me.bio||'')}</textarea></label><button class="primary">Salvar perfil profissional</button></form>`;pav.onchange=async()=>{avatarImage=await fileToData(pav.files[0],600);toast('Foto pronta para salvar.')};pcov.onchange=async()=>{coverImage=await fileToData(pcov.files[0],1800);toast('Capa pronta para salvar.')}}
async function saveProfile(e){e.preventDefault();try{await api('/api/profile',{method:'POST',body:JSON.stringify({name:pn.value,role:pr.value,headline:phl.value,company:pco.value,city:pcy.value,service_region:preg.value,experience:pex.value,completed_projects:ppj.value,response_time:prt.value,availability:pavl.value,specialties:psp.value,services:psv.value,equipment:peq.value,work_history:pwh.value,portfolio_links:ppl.value,certifications:pce.value,whatsapp:pwa.value,instagram:pig.value,website:pweb.value,bio:pbi.value,avatar:avatarImage,cover:coverImage})});me=(await api('/api/me')).user;headerName.textContent=me.name;if(window.sidebarName)sidebarName.textContent=me.name;toast('Perfil profissional atualizado.');loadAll()}catch(e){toast(e.message,true)}}
function openQuote(id,name){currentQuoteUser=id;quoteTitle.textContent=`Solicitar orçamento para ${name}`;quoteForm.reset();quoteName.value=me.name||'';quoteDlg.showModal()}
quoteClose.onclick=()=>quoteDlg.close();quoteForm.onsubmit=async e=>{e.preventDefault();try{await api(`/api/users/${currentQuoteUser}/quote`,{method:'POST',body:JSON.stringify({requester_name:quoteName.value,requester_phone:quotePhone.value,city:quoteCity.value,event_date:quoteDate.value,event_type:quoteType.value,audience:quoteAudience.value,message:quoteMessage.value})});quoteDlg.close();toast('Solicitação de orçamento enviada.')}catch(e){toast(e.message,true)}}
function openHire(){hireForm.reset();hireName.value=me.name||'';hireCity.value=me.city||'';hireDlg.showModal()}
hireClose.onclick=()=>hireDlg.close();
hireForm.onsubmit=async e=>{e.preventDefault();try{let result=await api('/api/hire-requests',{method:'POST',body:JSON.stringify({requester_name:hireName.value,requester_phone:hirePhone.value,city:hireCity.value,event_date:hireDate.value,event_type:hireType.value,audience:hireAudience.value,budget:hireBudget.value,equipment:hireEquipment.value,message:hireMessage.value})});lastHireMatches=result.matches||[];hireDlg.close();view='hire';toast('Especialistas encontrados.');renderHire(lastHireMatches,result.request_id)}catch(e){toast(e.message,true)}};
function matchCard(u){return `<article class="card match-card"><div class="match-score"><b>${u.score}%</b><span>compatibilidade</span></div>${avatar(u,'big')}<div class="match-main"><h3>${esc(u.name)}</h3><p class="match-headline">${esc(u.headline||u.role)}</p>${u.company?`<small>${esc(u.company)}</small>`:''}<p class="meta">${icon('location')} ${esc(u.city||'Cidade não informada')}</p><div class="skills">${lines(u.specialties)}</div><div class="match-facts"><span><b>${esc(u.experience||'—')}</b> experiência</span><span><b>${esc(u.completed_projects||'—')}</b> projetos</span><span><b>${esc(u.response_time||'Até 24h')}</b></span></div></div><div class="match-actions"><button class="secondary" onclick="openProfile(${u.id})">Ver perfil</button><button class="primary" onclick="openQuote(${u.id},${JSON.stringify(u.name)})">Solicitar orçamento</button></div></article>`}
async function renderHire(matches=null,requestId=null){let requests=[];try{requests=await api('/api/hire-requests')}catch{};let latest=matches||(requests[0]?.matches||[]);content.innerHTML=`<section class="hire-hero card"><div><span class="eyebrow">REDE SOCIAUDIO MATCH</span><h1>Contrate o especialista certo para o seu projeto</h1><p>Descreva sua necessidade e receba recomendações baseadas em cidade, especialidade, equipamentos e disponibilidade.</p><div class="hire-benefits"><span>✓ Profissionais por compatibilidade</span><span>✓ Perfis e experiência verificados</span><span>✓ Contato e orçamento direto</span></div><button class="primary hire-cta" onclick="openHire()">${icon('target')} Encontrar especialista</button></div><div class="hire-visual"><div class="pulse-ring">${icon('target')}</div><b>Busca inteligente</b><small>Conectando sua necessidade aos melhores profissionais da comunidade.</small></div></section>${latest.length?`<div class="section-heading"><div><h2>Profissionais recomendados</h2><p>${latest.length} perfis compatíveis com sua solicitação.</p></div><span class="request-number">Solicitação #${requestId||requests[0]?.id||''}</span></div><div class="matches-list">${latest.map(matchCard).join('')}</div>`:`<section class="card hire-empty"><div>${icon('professionals')}</div><h2>Pronto para encontrar um especialista?</h2><p>Crie sua primeira solicitação. As recomendações aparecerão aqui.</p><button class="primary" onclick="openHire()">Começar agora</button></section>`}${requests.length?`<section class="request-history"><div class="section-heading"><div><h2>Minhas solicitações</h2><p>Acompanhe os pedidos já criados.</p></div></div>${requests.map(r=>`<article class="card request-row"><div><span class="tag">${esc(r.status)}</span><h3>${esc(r.event_type||'Serviço de áudio')}</h3><p>${esc(r.city)}${r.event_date?` · ${esc(r.event_date)}`:''}${r.budget?` · ${esc(r.budget)}`:''}</p><small>${r.match_count} profissional(is) recomendado(s) · ${new Date(r.created_at).toLocaleString('pt-BR')}</small></div><button class="secondary" onclick='renderHire(${JSON.stringify(r.matches)},${r.id})'>Ver recomendações</button></article>`).join('')}</section>`:''}`;hydrateIcons(content)}
async function renderOpportunities(){let items=await api('/api/opportunities');content.innerHTML=`<div class="page-title"><h1>Oportunidades para você</h1><p>Solicitações compatíveis com seu perfil profissional.</p></div>${items.length?items.map(o=>`<article class="card opportunity-card"><div class="opportunity-score"><b>${o.score}%</b><small>compatibilidade</small></div><div><span class="tag">${esc(o.status)}</span><h2>${esc(o.event_type||'Serviço de áudio')}</h2><p class="meta">${icon('location')} ${esc(o.city)}${o.event_date?` · ${esc(o.event_date)}`:''}</p><p>${esc(o.message)}</p><div class="opportunity-info">${o.audience?`<span>Público: <b>${esc(o.audience)}</b></span>`:''}${o.budget?`<span>Orçamento: <b>${esc(o.budget)}</b></span>`:''}${o.equipment?`<span>Equipamentos: <b>${esc(o.equipment)}</b></span>`:''}</div><small>Solicitado por ${esc(o.requester_name)} · ${new Date(o.created_at).toLocaleString('pt-BR')}</small></div>${o.requester_phone?`<a class="primary btn" target="_blank" href="https://wa.me/${o.requester_phone.replace(/\D/g,'')}">Falar no WhatsApp</a>`:''}</article>`).join(''):'<div class="empty">Ainda não há oportunidades compatíveis. Complete seu perfil para melhorar as recomendações.</div>'}`;hydrateIcons(content)}
async function renderRequests(){let items=await api('/api/quote-requests');content.innerHTML=`<div class="page-title"><h1>Solicitações de orçamento</h1><p>Pedidos enviados por possíveis clientes.</p></div>${items.length?items.map(q=>`<article class="card quote-card"><div><span class="tag">${esc(q.status)}</span><h3>${esc(q.requester_name)}</h3><p><b>${esc(q.event_type||'Serviço de áudio')}</b> · ${esc(q.city||'Cidade não informada')}</p><p>${esc(q.message)}</p><small>${q.event_date?`Data: ${esc(q.event_date)} · `:''}${q.audience?`Público: ${esc(q.audience)} · `:''}${new Date(q.created_at).toLocaleString('pt-BR')}</small></div>${q.requester_phone?`<a class="primary btn" target="_blank" href="https://wa.me/${q.requester_phone.replace(/\D/g,'')}">Responder no WhatsApp</a>`:''}</article>`).join(''):'<div class="empty">Nenhuma solicitação recebida ainda.</div>'}`}
function companyLogo(c,cls=''){return c.logo?`<img class="company-logo ${cls}" src="${c.logo}">`:`<div class="company-logo placeholder ${cls}">${esc((c.name||'E').slice(0,2).toUpperCase())}</div>`}
async function renderCompanies(){let items=await api('/api/companies');content.innerHTML=`<div class="page-title company-page-title"><div><h1>Empresas</h1><p>Conheça empresas, integradores, lojas, igrejas e marcas da comunidade.</p></div><button class="primary" onclick="editMyCompany()">${icon('plus')} Criar ou editar minha empresa</button></div><div class="company-grid">${items.map(c=>`<article class="card company-card"><div class="company-cover-mini" style="${c.cover?`background-image:url('${c.cover}')`:''}"></div><div class="company-card-body">${companyLogo(c)}<div class="company-title-row"><h2>${esc(c.name)}</h2>${c.verified?'<span class="verified-badge">✓</span>':''}</div><span class="tag">${esc(c.category||'Empresa de áudio')}</span><p>${esc(c.tagline||c.description||'Empresa da comunidade Rede Sociaudio.')}</p><small>${icon('location')} ${esc(c.city||'Localização não informada')}</small><div class="company-metrics"><span><b>${c.services_count}</b> serviços</span><span><b>${c.projects_count}</b> projetos</span></div><button class="primary" onclick="openCompany(${c.id})">Ver página</button></div></article>`).join('')}</div>`;hydrateIcons(content)}
async function openCompany(id){let c=await api(`/api/companies/${id}`);view='companies';content.innerHTML=`<section class="company-profile"><div class="company-hero card"><div class="company-cover" style="${c.cover?`background-image:url('${c.cover}')`:''}"></div><div class="company-identity">${companyLogo(c,'large')}<div><div class="company-title-row"><h1>${esc(c.name)}</h1>${c.verified?'<span class="verified-badge">✓ Empresa verificada</span>':''}</div><h3>${esc(c.tagline||c.category)}</h3><p>${icon('location')} ${esc(c.city||'Localização não informada')} · ${esc(c.service_region||'Atendimento a combinar')}</p></div><div class="company-actions">${c.whatsapp?`<a class="primary btn" target="_blank" href="https://wa.me/${c.whatsapp.replace(/\D/g,'')}">WhatsApp</a>`:''}${c.website?`<a class="secondary btn" target="_blank" href="${esc(c.website)}">Site</a>`:''}${c.can_edit?`<button class="secondary" onclick="editMyCompany(${c.id})">Editar empresa</button>`:''}</div></div></div><div class="company-layout"><main><section class="card company-section"><h2>Sobre</h2><p>${esc(c.description||'Esta empresa ainda não adicionou uma descrição.')}</p></section><section class="company-section"><div class="section-heading"><div><h2>Serviços</h2><p>Soluções oferecidas pela empresa.</p></div></div><div class="service-grid">${c.services.length?c.services.map(s=>`<article class="card service-card"><span>${esc(s.icon||'🎚️')}</span><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p></article>`).join(''):'<div class="empty">Nenhum serviço cadastrado.</div>'}</div></section><section class="company-section"><div class="section-heading"><div><h2>Projetos</h2><p>Trabalhos e cases realizados.</p></div></div><div class="project-grid">${c.projects.length?c.projects.map(p=>`<article class="card project-card">${p.image?`<img src="${p.image}">`:''}<div><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p>${p.link_url?`<a target="_blank" href="${esc(p.link_url)}">Ver projeto</a>`:''}</div></article>`).join(''):'<div class="empty">Nenhum projeto cadastrado.</div>'}</div></section><section class="company-section"><div class="section-heading"><div><h2>Equipe</h2><p>Pessoas que fazem parte da empresa.</p></div></div><div class="team-grid">${c.team.length?c.team.map(t=>`<article class="card team-card">${t.photo?`<img src="${t.photo}">`:`<div class="team-avatar">${esc(t.name.slice(0,1))}</div>`}<h3>${esc(t.name)}</h3><b>${esc(t.role)}</b><p>${esc(t.bio)}</p></article>`).join(''):'<div class="empty">Nenhum integrante cadastrado.</div>'}</div></section></main><aside class="card company-contact"><h3>Contato</h3>${c.phone?`<p><b>Telefone</b><br>${esc(c.phone)}</p>`:''}${c.email?`<p><b>E-mail</b><br>${esc(c.email)}</p>`:''}${c.instagram?`<p><b>Instagram</b><br>${esc(c.instagram)}</p>`:''}<p><b>Responsável</b><br>${esc(c.owner_name)}</p></aside></div></section>`;hydrateIcons(content)}
async function editMyCompany(id=null){let companies=await api('/api/companies');let mine=companies.find(x=>x.owner_id===me.id);let c=mine?await api(`/api/companies/${mine.id}`):{name:me.company||'',category:'Empresa de áudio',tagline:'',description:'',city:me.city||'',service_region:me.service_region||'',phone:'',whatsapp:me.whatsapp||'',email:me.email||'',instagram:me.instagram||'',website:me.website||'',logo:'',cover:'',services:[],team:[],projects:[]};let services=(c.services||[]).map(x=>`${x.icon||'🎚️'}|${x.title}|${x.description}`).join('\n'),team=(c.team||[]).map(x=>`${x.name}|${x.role}|${x.bio}`).join('\n'),projects=(c.projects||[]).map(x=>`${x.title}|${x.description}|${x.link_url||''}`).join('\n');content.innerHTML=`<div class="page-title"><div><h1>Página da empresa</h1><p>Crie uma apresentação profissional para sua marca.</p></div></div><form class="card profile-grid" onsubmit="saveCompany(event)"><label class="wide">Nome da empresa<input id="coName" required value="${esc(c.name||'')}"></label><label>Categoria<input id="coCategory" value="${esc(c.category||'')}"></label><label>Cidade<input id="coCity" value="${esc(c.city||'')}"></label><label class="wide">Frase de posicionamento<input id="coTagline" value="${esc(c.tagline||'')}"></label><label class="wide">Descrição<textarea id="coDescription">${esc(c.description||'')}</textarea></label><label>Região de atendimento<input id="coRegion" value="${esc(c.service_region||'')}"></label><label>Telefone<input id="coPhone" value="${esc(c.phone||'')}"></label><label>WhatsApp<input id="coWhatsapp" value="${esc(c.whatsapp||'')}"></label><label>E-mail<input id="coEmail" value="${esc(c.email||'')}"></label><label>Instagram<input id="coInstagram" value="${esc(c.instagram||'')}"></label><label>Site<input id="coWebsite" value="${esc(c.website||'')}"></label><label>Logo<input id="coLogoFile" type="file" accept="image/*"></label><label>Imagem de capa<input id="coCoverFile" type="file" accept="image/*"></label><label class="wide">Serviços <small>Formato: ícone|título|descrição, um por linha</small><textarea id="coServices">${esc(services)}</textarea></label><label class="wide">Equipe <small>Formato: nome|função|biografia, um por linha</small><textarea id="coTeam">${esc(team)}</textarea></label><label class="wide">Projetos <small>Formato: título|descrição|link, um por linha</small><textarea id="coProjects">${esc(projects)}</textarea></label><button class="primary">Salvar página empresarial</button></form>`;window.companyEditing=c;coLogoFile.onchange=async()=>{window.companyEditing.logo=await fileToData(coLogoFile.files[0],600);toast('Logo pronta para salvar.')};coCoverFile.onchange=async()=>{window.companyEditing.cover=await fileToData(coCoverFile.files[0],1800);toast('Capa pronta para salvar.')}}
async function saveCompany(e){e.preventDefault();let parse=(text,kind)=>text.split('\n').map(x=>x.trim()).filter(Boolean).map(line=>{let p=line.split('|').map(x=>x.trim());if(kind==='service')return{icon:p[0]||'🎚️',title:p[1]||p[0],description:p.slice(2).join('|')};if(kind==='team')return{name:p[0],role:p[1]||'',bio:p.slice(2).join('|')};return{title:p[0],description:p[1]||'',link_url:p[2]||''}});try{let r=await api('/api/companies',{method:'POST',body:JSON.stringify({name:coName.value,category:coCategory.value,tagline:coTagline.value,description:coDescription.value,city:coCity.value,service_region:coRegion.value,phone:coPhone.value,whatsapp:coWhatsapp.value,email:coEmail.value,instagram:coInstagram.value,website:coWebsite.value,logo:window.companyEditing.logo||'',cover:window.companyEditing.cover||'',services:parse(coServices.value,'service'),team:parse(coTeam.value,'team'),projects:parse(coProjects.value,'project')})});toast('Página empresarial atualizada.');openCompany(r.id)}catch(err){toast(err.message,true)}}
async function renderNotifications(){content.innerHTML='<div class="page-title"><h1>Notificações</h1></div>'+((notifications.items||[]).length?notifications.items.map(n=>`<article class="card notification ${n.is_read?'':'unread'}"><span>${n.type==='comment'?icon('comment'):n.type==='like'?icon('like'):icon('profile')}</span><div><b>${esc(n.message)}</b><p class="meta">${new Date(n.created_at).toLocaleString('pt-BR')}</p></div></article>`).join(''):'<div class="empty">Você ainda não possui notificações.</div>');if(notifications.unread){await api('/api/notifications/read',{method:'POST'});notifications.unread=0;bellCount.textContent=''}}

let adminAssistantPending=null;

function adminAssistantMessage(role,text,action=null,logId=0){
  let box=document.querySelector('#adminAssistantMessages');
  if(!box)return;
  let item=document.createElement('div');
  item.className='admin-ai-message '+role;
  item.innerHTML=`<span>${role==='user'?'Você':'Assistente'}</span><p>${esc(text)}</p>`;
  if(action){
    adminAssistantPending={action,log_id:logId};
    let controls=document.createElement('div');
    controls.className='admin-ai-confirm';
    controls.innerHTML=`<b>${esc(action.label||'Confirmar alteração')}</b><button class="primary" onclick="confirmAdminAssistantAction()">Confirmar</button><button class="secondary" onclick="cancelAdminAssistantAction()">Cancelar</button>`;
    item.appendChild(controls);
  }
  box.appendChild(item);
  box.scrollTop=box.scrollHeight;
}

async function askAdminAssistant(){
  let input=document.querySelector('#adminAssistantInput');
  let button=document.querySelector('#adminAssistantSend');
  let prompt=input?.value.trim();
  if(!prompt)return;
  adminAssistantMessage('user',prompt);
  input.value='';
  try{
    button.disabled=true;
    button.textContent='Analisando...';
    let result=await api('/api/admin/assistant',{method:'POST',body:JSON.stringify({prompt})});
    adminAssistantMessage('assistant',result.reply,result.action,result.log_id);
  }catch(e){
    adminAssistantMessage('assistant',e.message);
  }finally{
    button.disabled=false;
    button.textContent='Enviar';
  }
}

async function confirmAdminAssistantAction(){
  if(!adminAssistantPending)return;
  try{
    let result=await api('/api/admin/assistant/execute',{
      method:'POST',
      body:JSON.stringify(adminAssistantPending)
    });
    adminAssistantPending=null;
    adminAssistantMessage('assistant',result.message);
    await applyPlatformSettings();
    await loadAll();
    setTimeout(()=>renderAdmin(),250);
  }catch(e){
    adminAssistantMessage('assistant',e.message);
  }
}

function cancelAdminAssistantAction(){
  adminAssistantPending=null;
  adminAssistantMessage('assistant','A alteração foi cancelada.');
}

function adminAssistantKeydown(event){
  if(event.key==='Enter'&&!event.shiftKey){
    event.preventDefault();
    askAdminAssistant();
  }
}

async function setUserPlan(id,plan){try{await api(`/api/admin/users/${id}/plan`,{method:'POST',body:JSON.stringify({plan})});toast('Plano atualizado.');await loadAll();renderAdmin()}catch(e){toast(e.message,true)}}

async function downloadAdminBackup(){if(!me?.is_admin)return toast('Acesso restrito ao administrador.',true);if(!confirm('Gerar e baixar agora um backup completo do banco, usuários, mensagens e uploads?'))return;let btn=document.querySelector('#adminBackupBtn');try{if(btn){btn.disabled=true;btn.textContent='Gerando backup...'}let r=await fetch('/api/admin/backup',{headers:{Authorization:'Bearer '+token}});if(!r.ok){let d=await r.json().catch(()=>({}));throw Error(d.error||'Não foi possível gerar o backup.')}let blob=await r.blob(),disposition=r.headers.get('Content-Disposition')||'',match=disposition.match(/filename="?([^";]+)"?/i),filename=match?.[1]||`redesociaudio-backup-${new Date().toISOString().slice(0,10)}.zip`,url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Backup baixado. Guarde o arquivo em local seguro.')}catch(e){toast(e.message,true)}finally{if(btn){btn.disabled=false;btn.textContent='Baixar backup completo'}}}
